#include <iostream>
#include <numeric>
#include <print>
#include <stdexcept>

class Fraction {
public:
    Fraction(long long numerator, long long denominator) {
        if (denominator == 0) {
            throw std::invalid_argument("знаменатель равен нулю");
        }
        if (denominator < 0) {
            numerator = -numerator;
            denominator = -denominator;
        }
        long long g = std::gcd(numerator, denominator);
        num_ = numerator / g;
        den_ = denominator / g;
    }

    void print() const {
        std::println("{}/{}", num_, den_);
    }

private:
    long long num_;
    long long den_;
};

int main() {
    long long a, b;
    while (std::cin >> a >> b) {
        try {
            Fraction f(a, b);
            f.print();
        } catch (const std::invalid_argument &e) {
            std::println("ошибка: {}", e.what());
        }
    }
    return 0;
}

