#include <iostream>
#include <print>
#include <string>

class Duration {
public:
    explicit Duration(int minutes) : minutes_(minutes < 0 ? 0 : minutes) {}
    Duration(int hours, int minutes) : Duration(hours * 60 + minutes) {}

    int minutes() const {
        return minutes_;
    }

    void print(const char *prefix) const {
        std::println("{}{} ч {} мин", prefix, minutes_ / 60, minutes_ % 60);
    }

private:
    int minutes_;
};

int main() {
    std::string kind;
    int total = 0;
    while (std::cin >> kind) {
        int a, b = 0;
        std::cin >> a;
        if (kind == "hm") {
            std::cin >> b;
        }
        Duration d = kind == "hm" ? Duration(a, b) : Duration(a);
        d.print("");
        total += d.minutes();
    }
    Duration(total).print("всего ");
    return 0;
}

